locals {
  resource_di_bindings = local.env != "pro" ? [
    azurerm_container_app_environment_dapr_component.bindings_cpt_faurecia_dbo_shift_tracking_status_rsrce_di,
    azurerm_container_app_environment_dapr_component.bindings_cpt_faurecia_dbo_shift_tracking_rsrce_di
  ] : [
    azurerm_container_app_environment_dapr_component.bindings_cpt_faurecia_dbo_shift_tracking_status_rsrce_di,
    azurerm_container_app_environment_dapr_component.bindings_cpt_faurecia_dbo_shift_tracking_rsrce_di
  ]

  # KEDA scaling thresholds - centralized for easy tuning
  keda_thresholds = {
    activation_threshold   = "0"
    unprocessed_threshold  = "1000"
    checkpoint_strategy    = "blobMetadata"
  }

  # EventHub scaling rules configuration
  eventhub_scale_rules = !local.enable_resource_dapr_bindings && local.enable_resource_data_ingestion_auto_scale ? [
    {
      name                  = "shift-tracking"
      eventhub_namespace    = data.azurerm_eventhub.cpt_faurecia_dbo_shift_tracking.0.namespace_name
      eventhub_name         = data.azurerm_eventhub.cpt_faurecia_dbo_shift_tracking.0.name
      consumer_group        = azurerm_eventhub_consumer_group.cpt_faurecia_dbo_shift_tracking_v2_evh_sdk.0.name
      storage_account_name  = azurerm_storage_container.evh_sdk_cpt_faurecia_dbo_shift_tracking_v2.0.storage_account_name
      blob_container        = azurerm_storage_container.evh_sdk_cpt_faurecia_dbo_shift_tracking_v2.0.name
    },
    {
      name                  = "shift-tracking-status"
      eventhub_namespace    = data.azurerm_eventhub.cpt_faurecia_dbo_shift_tracking_status.0.namespace_name
      eventhub_name         = data.azurerm_eventhub.cpt_faurecia_dbo_shift_tracking_status.0.name
      consumer_group        = azurerm_eventhub_consumer_group.cpt_faurecia_dbo_shift_tracking_status_v2_evh_sdk.0.name
      storage_account_name  = azurerm_storage_container.evh_sdk_cpt_faurecia_dbo_shift_tracking_status_v2.0.storage_account_name
      blob_container        = azurerm_storage_container.evh_sdk_cpt_faurecia_dbo_shift_tracking_status_v2.0.name
    }
  ] : []

  # Generate Dapr binding scale rules from bindings
  dapr_binding_scale_rules = local.enable_resource_dapr_bindings && local.enable_resource_data_ingestion_auto_scale ? [
    for binding in local.resource_di_bindings : {
      name                  = replace(binding.name, "bindings-", "")
      eventhub_namespace    = replace([for m in binding.metadata : m["value"] if m["name"] == "eventHubNamespace"][0], ".servicebus.windows.net", "")
      eventhub_name         = [for m in binding.metadata : m["value"] if m["name"] == "eventHub"][0]
      consumer_group        = [for m in binding.metadata : m["value"] if m["name"] == "consumerGroup"][0]
      storage_account_name  = [for m in binding.metadata : m["value"] if m["name"] == "storageAccountName"][0]
      blob_container        = [for m in binding.metadata : m["value"] if m["name"] == "storageContainerName"][0]
    }
  ] : []

  # Combine all scale rules
  all_scale_rules = concat(local.eventhub_scale_rules, local.dapr_binding_scale_rules)

  # Generate KEDA scale rules in the required format
  keda_scale_rules = concat(
    local.enable_resource_data_ingestion_auto_scale ? [
      for rule in local.all_scale_rules : {
        name = rule.name
        custom = {
          type     = "azure-eventhub"
          identity = data.azurerm_user_assigned_identity.main.id
          metadata = {
            eventHubNamespace                   = rule.eventhub_namespace
            eventHubName                        = rule.eventhub_name
            consumerGroup                       = rule.consumer_group
            storageAccountName                  = rule.storage_account_name
            blobContainer                       = rule.blob_container
            activationUnprocessedEventThreshold = local.keda_thresholds.activation_threshold
            unprocessedEventThreshold           = local.keda_thresholds.unprocessed_threshold
            checkpointStrategy                  = local.keda_thresholds.checkpoint_strategy
          }
        }
      }
    ] : [],
    local.enable_resource_data_ingestion_auto_scale ? [
      {
        name = "cpu-scaling"
        custom = {
          type = "cpu"
          metadata = {
            type  = "Utilization"
            value = "80"
          }
        }
      },
      {
        name = "memory-scaling"
        custom = {
          type = "memory"
          metadata = {
            type  = "Utilization"
            value = "80"
          }
        }
      }
    ] : []
  )
}

