resource "azapi_resource" "caj_data_ingestion_work_data_cleansing_job" {
  for_each  = local.enable_data_ingestion ? tomap(local.data_ingestion_domains) : tomap({})
  type      = "Microsoft.App/jobs@2023-05-01"
  name      = "caj-${local.subscription}-${local.region}-${local.env}-${each.key}"
  location  = data.azurerm_resource_group.mes.location
  parent_id = data.azurerm_resource_group.mes.id
  tags      = local.resource_tags

  identity {
    type = "UserAssigned"
    identity_ids = [
      data.azurerm_user_assigned_identity.main.id
    ]
  }

  body = jsonencode({
    properties = {
      configuration = {
        registries = [
          {
            identity = data.azurerm_user_assigned_identity.main.id
            server   = "acrgptmpxp01static01.azurecr.io"
          }
        ]
        replicaTimeout    = 1800,
        replicaRetryLimit = 5,
        triggerType       = "Schedule",
        scheduleTriggerConfig = {
          cronExpression         = var.DATA_INGESTION_CLEANSING_JOB_CRON_PATTERN
          parallelism            = 1,
          replicaCompletionCount = 1,
        },
      }
      environmentId = data.azapi_resource.cae_main.id
      template = {
        containers = [
          {
            env     = []
            image   = "acrgptmpxp01static01.azurecr.io/mirror/registry.hub.docker.com/alpine/curl:8.12.1"
            name    = "${each.key}"
            command = ["sh", "-c"]
            # 2 seconds delay to allow for network config to complete #117704
            args = ["sleep 2 && curl -X DELETE http://${each.value}/data-ingestion/deleteExpiredIngestionEventTracking --max-time ${var.DATA_INGESTION_CLEANSING_JOB_TIMEOUT_SECONDS} --fail-with-body"]
            resources = {
              cpu    = 0.25
              memory = "0.5Gi"
            }
          }
        ]
      }
      workloadProfileName = "Consumption"
    }
  })
}

