resource "azapi_resource" "ca_admin_backend" {
  count     = local.enable_admin ? 1 : 0
  type      = "Microsoft.App/containerApps@2023-05-01"
  name      = "ca-${local.subscription}-${local.region}-${local.env}-${local.app_id_admin_backend}"
  location  = data.azurerm_resource_group.mes.location
  parent_id = data.azurerm_resource_group.mes.id
  tags      = local.resource_tags

  identity {
    type = "UserAssigned"
    identity_ids = [
      data.azurerm_user_assigned_identity.main.id
    ]
  }

  body = jsonencode({
    properties = {
      configuration = {
        dapr = {
          appId       = local.app_id_admin_backend
          appPort     = 3000
          appProtocol = "http"
          enabled     = true
          logLevel    = local.env == "pro" ? "warn" : "info"
        }
        activeRevisionsMode = "Single"
        ingress = {
          allowInsecure = true
          external      = false
          targetPort    = 3000
          corsPolicy = {
            allowedOrigins   = ["*"]
            allowedMethods   = ["*"]
            allowedHeaders   = ["*"]
            allowCredentials = true
          }
        }
        registries = [
          {
            identity = data.azurerm_user_assigned_identity.main.id
            server   = "acrgptmpxp01static01.azurecr.io"
          }
        ]
      }
      environmentId = data.azapi_resource.cae_main.id
      template = {
        containers = [
          {
            env = [
              {
                name  = "URL_ADMIN_BACKEND"
                value = "https://${local.fqdn}/${local.app_id_admin_backend}"
              },
              {
                name  = "SHIP_API_APP_ID"
                value = local.app_id_shipment_api
              },
              {
                name  = "PLANT_HIERARCHY_API_APP_ID"
                value = local.app_id_plant_hierarchy_api
              },
              {
                name  = "ORDER_API_APP_ID"
                value = local.app_id_order_api
              },
              {
                name  = "AZURE_TENANT_ID"
                value = data.azurerm_user_assigned_identity.main.tenant_id
              },
              {
                name  = "AZURE_CLIENT_ID"
                value = data.azurerm_user_assigned_identity.main.client_id
              },
              {
                name  = "APP_CONFIG_ENDPOINT"
                value = jsondecode(data.azapi_resource.app_config_mes[0].output).properties.endpoint
              },
              {
                name  = "MASTER_API_APP_ID"
                value = local.app_id_master_api
              },
              {
                name  = "PRODUCTION_API_APP_ID"
                value = local.app_id_production_api
              },
              {
                name  = "APPLICATIONINSIGHTS_CONNECTION_STRING"
                value = data.azurerm_application_insights.main.connection_string
              },
              {
                name  = "UME_API_APP_ID"
                value = local.app_id_ume_api
              },
              {
                name  = "ORDER_MANAGEMENT_API_APP_ID"
                value = local.app_id_order_management_api
              },
              {
                name  = "COSMOS_DB_ENDPOINT"
                value = data.azurerm_cosmosdb_account.main_mes.endpoint
              },
              {
                name  = "COSMOS_DB_DATABASE"
                value = data.azurerm_cosmosdb_sql_database.mes_new.name
              },
              {
                name  = "COSMOS_DB_CONTAINER_PAGE_BUILDER"
                value = azurerm_cosmosdb_sql_container.page_builder.name
              }
            ]
            image = "acrgptmpxp01static01.azurecr.io/mesx/admin-backend:${local.service_versions["admin_backend"][local.env]}"
            name  = local.app_id_admin_backend
            probes = [
              {
                httpGet = {
                  path   = "/"
                  port   = 3000
                  scheme = "HTTP"
                }
                initialDelaySeconds = 30
                periodSeconds       = 10
                successThreshold    = 1
                failureThreshold    = 3
                timeoutSeconds      = 5
                type                = "Liveness"
              }
            ]
            resources = {
              cpu    = 0.25
              memory = "0.5Gi"
            }
          }
        ]
        scale = {
          minReplicas = local.env != "dev" ? 1 : 0
          maxReplicas = 2
          rules = [
            {
              name = "http"
              http = {
                metadata = {
                  concurrentRequests = "40"
                }
              }
            }
          ]
        }
      }
      workloadProfileName = "Consumption"
    }
  })
}

