resource "azapi_resource" "ca_app_proxy_auth" {
  count     = 0
  type      = "Microsoft.App/containerApps/authConfigs@2024-03-01"
  name      = "current"
  parent_id = azapi_resource.ca_app_proxy[0].id
  body = jsonencode({
    properties = {
      globalValidation = {
        excludedPaths = [
          "/plt-hry-api/plant/uploadplants",
          "/downtime-be/downtime/get-downtime-cause-changes",
          "/datahub",
          "/datahub/*",
          "/wkint-be",
          "/wkint-be/*",
        ]
        redirectToProvider          = "customOpenIdConnectProviders"
        unauthenticatedClientAction = "RedirectToLoginPage"
      }
      httpSettings = {
        requireHttps = true
      }
      identityProviders = {
        customOpenIdConnectProviders = {
          pingFederate = {
            enabled = true
            login = {
              nameClaimType = "username"
              scopes        = split(" ", local.identity_provider_app_scopes)
            }
            registration = {
              clientCredential = {
                #checkov:skip=CKV_SECRET_6:The secret name is detected as an actual secret
                clientSecretSettingName = "identity-provider-client-secret"
                method                  = "ClientSecretPost"
              }
              clientId = local.identity_provider_app_client_id_backend
              openIdConnectConfiguration = {
                authorizationEndpoint        = "${local.identity_provider_app_authority}/as/authorization.oauth2"
                certificationUri             = "${local.identity_provider_app_authority}/pf/JWKS"
                issuer                       = local.identity_provider_app_authority
                tokenEndpoint                = "${local.identity_provider_app_authority}/as/token.oauth2"
                wellKnownOpenIdConfiguration = "${local.identity_provider_app_authority}/.well-known/openid-configuration"
              }
            }
          }
        }
      }
      login = {
        cookieExpiration = {
          convention       = "FixedTime"
          timeToExpiration = "14.00:00:00"
        }
      }
      platform = {
        enabled = true
      }
    }
  })
}

