                name  = "IDENTITY_PROVIDER_APP_AUTHORITY"
                value = local.identity_provider_app_authority
              },
              {
                name  = "IDENTITY_PROVIDER_APP_SCOPES"
                value = local.identity_provider_app_scopes
              },
              {
                name  = "IDENTITY_PROVIDER_APP_RESPONSE_TYPE"
                value = local.identity_provider_app_response_type
              },
              {
                name  = "URL_UME_BACKEND"
                value = "https://${local.fqdn}/${local.app_id_ume_backend}"
              },
              {
                name  = "WK_INTEGRATION_BACKEND_URL"
                value = "https://${local.fqdn}/${local.app_id_wk_integration_backend}"
              },
              {
                name  = "UME_API_URL"
                value = "https://${local.fqdn}/${local.app_id_ume_api}"
              },
              {
                name  = "TOKEN"
                value = ""
              },
              {
                name  = "ACCESS_TOKEN_EXPIRING_REFRESH_SECONDS"
                value = "2640"
              }
            ]
            image = "acrgptmpxp01static01.azurecr.io/mesx/wk-integration-ui:${local.service_versions["wk_integration_ui"][local.env]}"
            name  = local.app_id_wk_integration_ui
            probes = [
              {
                httpGet = {
                  path   = "/"
                  port   = 3000
                  scheme = "HTTP"
                }
                initialDelaySeconds = 30
                periodSeconds       = 10
                successThreshold    = 1
                failureThreshold    = 3
                type                = "Liveness"
              }
            ]
            resources = {
              cpu    = 0.25
              memory = "0.5Gi"
            }
          }
        ]
        scale = {
          minReplicas = local.env != "dev" ? 1 : 0
          maxReplicas = 2
          rules = [
            {
              name = "http"
              http = {
                metadata = {
                  concurrentRequests = "40"
                }
              }
            }
          ]
        }
      }
      workloadProfileName = "Consumption"
    }
  })
}

